import assert from 'node:assert/strict';
import { test } from 'node:test';
import { stripFooter } from './pr-description.mjs';

test('removes the footers tools add, and the separator above them', () => {
  assert.equal(
    stripFooter(
      'Add X.\n\n- one\n- two\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_\n',
    ),
    'Add X.\n\n- one\n- two',
  );
  assert.equal(
    stripFooter(
      'Fix Y.\n\n🤖 Generated with [Claude Code](https://claude.com/claude-code)\n\nhttps://claude.ai/code/session_123\r\n',
    ),
    'Fix Y.',
  );
  assert.equal(
    stripFooter(
      'Fix Z.\n\nCo-Authored-By: Someone <a@b.c>\nClaude-Session: https://claude.ai/code/x',
    ),
    'Fix Z.',
  );
});

test('leaves text alone that only looks similar or is not at the end', () => {
  const body = 'Mentions Co-Authored-By: trailers.\n\n---\n\nMore text.';
  assert.equal(stripFooter(body), body);
  assert.equal(stripFooter('Plain.'), 'Plain.');
  assert.equal(stripFooter(null), '');
});
